const retry = document.querySelector('#booking-retry')
const previous = document.querySelector('#booking-previous')
const range = document.querySelector('#booking-range')

previous.addEventListener('click', () => {
  if (busy || locked || !date.value || !date.validity.valid || date.value <= date.min) return
  const target = addDays(date.value, -7)
  date.value = target < date.min ? date.min : target
  load()
})
next.addEventListener('click', () => {
  if (busy || locked) return
  date.value = addDays(date.value || date.min, 7)
  load()
})

